#!/usr/bin/env python3
import json,html
from pathlib import Path
P=Path(__file__).resolve().parent
images=json.loads((P/'images/manifest.json').read_text());videos=json.loads((P/'video/manifest.json').read_text())['videos']
def rel(path):return Path(path).relative_to(P.relative_to(P.parents[2])).as_posix()
rows=[];cards=[]
for r in images:
 src=rel(r['path']);rows.append({**r,'file':r['path'],'review':'검토 대기(제작 반영)','preview_url':'http://127.0.0.1:4471/?slot='+r['slot']})
 cards.append(f'<article data-slot="{r["slot"]}"><h2>{html.escape(r["name"])}</h2><div class="image"><img src="{src}" alt="{html.escape(r["name"])}"></div><p>{"기존 파일 그대로 사용" if r.get("source") else "신규 원화 · 검토 대기"}</p><a href="{src}" download>PNG 받기</a><small>{r["slot"]}</small></article>')
for r in videos:
 src=rel(r['file']);poster=rel(r['poster']);rows.append({'slot':r['slot'],'name':r['title'],'file':r['file'],'poster':r['poster'],'sha256':r['sha256'],'poster_sha256':r['poster_sha256'],'review':'검토 대기(제작 반영)','kind':r['kind'],'current_match_active':r.get('current_match_active'),'preview_url':'http://127.0.0.1:4471/?slot='+r['slot']})
 label='기존 모션 소개 · 무음' if 'accessory/iron-armor' not in r['slot'] else '정보 소개 · 무음'
 if r.get('current_match_active') is False:label+=' · 현재 경기 비활성'
 cards.append(f'<article data-slot="{r["slot"]}"><h2>{html.escape(r["title"])}</h2><video controls playsinline preload="metadata" poster="{poster}"><source src="{src}" type="video/mp4"></video><p>{label}</p><button type="button">재생</button> <a href="{src}" download>MP4 받기</a><small>{r["slot"]}</small></article>')
body='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forest Arena · MENU09 미디어 검토</title><style>*{box-sizing:border-box}body{margin:0;background:#10181c;color:#f2f3ed;font-family:system-ui,sans-serif}header{padding:36px 5%;border-bottom:1px solid #455455}h1{font-size:32px;margin:0 0 12px}header p{color:#bbc6c6;line-height:1.6;margin:8px 0}nav{display:flex;gap:16px;flex-wrap:wrap;margin-top:20px}button,a{background:#d9c58e;border:0;border-radius:8px;color:#10181c;padding:12px 20px;font-size:16px;cursor:pointer;text-decoration:none;display:inline-block}main{padding:32px 5%;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,500px),1fr));gap:24px}article{background:#1c282c;border:1px solid #455455;border-radius:16px;padding:24px}h2{font-size:24px;margin:0 0 20px}video{width:100%;aspect-ratio:16/9;display:block;background:#10181c;border-radius:8px}.image{height:300px;display:grid;place-items:center}.image img{max-width:100%;max-height:100%;object-fit:contain}small{display:block;color:#bbc6c6;margin-top:20px;word-break:break-all}article p{color:#bbc6c6;line-height:1.6}article[hidden]{display:none}</style><header><h1>MENU09 · 미디어 검토</h1><p>이미지 7종 · 영상 22종 — 신규 신기 원화 6종, 기존 실버 문양과 승인 모션 재사용</p><p>자산 반영본은 검토 대기입니다. 영상은 기존 원화·동작을 편집한 소개 미디어이며 실제 전투 판정 녹화가 아닙니다.<br>이 페이지는 현재 컴퓨터의 검토 서버에서 재생합니다. 게임 적용과 Android 실기기 확인은 별도로 진행합니다.</p><nav><button id="all">전체 29종</button><button id="images">이미지 7종</button><button id="videos">영상 22종</button><a href="asset-map.json" download>슬롯 대응표 받기</a></nav></header><main>'''+''.join(cards)+'''</main><script>const cards=[...document.querySelectorAll('article')];function filter(f){cards.forEach(c=>{c.hidden=!f(c);if(c.hidden)c.querySelector('video')?.pause()})}document.querySelector('#all').onclick=()=>{filter(()=>true);history.replaceState(null,'',location.pathname)};document.querySelector('#images').onclick=()=>filter(c=>c.dataset.slot.startsWith('IMG/'));document.querySelector('#videos').onclick=()=>filter(c=>c.dataset.slot.startsWith('VIDEO/'));cards.forEach(c=>{let b=c.querySelector('button');if(b)b.onclick=()=>{let v=c.querySelector('video');document.querySelectorAll('video').forEach(o=>{if(o!==v)o.pause()});v.currentTime=0;v.play()}});const slot=new URLSearchParams(location.search).get('slot');if(slot)filter(c=>c.dataset.slot===slot);</script></html>'''
(P/'index.html').write_text(body);(P/'asset-map.json').write_text(json.dumps({'revision':'media-assets-r01','count':len(rows),'native_penpot_video':False,'preview_server':'127.0.0.1:4471','assets':rows},ensure_ascii=False,indent=2));print(len(rows),'slots')
